/*
 */
 float feedback;
float hset;
float e,uk,ukm1,ukm2,ekm1,ekm2,BN;
void setup() {

for (int i=0;i<=7;i++){
  pinMode(i,OUTPUT);
}


}

void loop() {
  feedback=analogRead(A1)/1023.0*5.0;
  hset=analogRead(A0)/1023.0*5.0*10.0;
  e=hset-feedback;
  uk=0.1276*ekm1-0.1244*ekm2+1.84*ukm1-0.849*ukm2;

 BN=uk*255.0/5.0/6.0;
  PORTD=BN;

  ukm2=ukm1;
  ukm1=uk;
  ekm2=ekm1;
  ekm1=e;

  delay(100);

}
